int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    /* Adjust offset to be even */
    if (offset % 2 != 0) {
        offset++;
    }

    /* Get the length of the remaining bytes in tvb */
    guint length = tvb_reported_length_remaining(tvb, offset);
    if (length % 2 != 0) {
        /* Adjust length to be even */
        length--;
    }

    if (length == 0) {
        /* No string to dissect */
        return offset;
    }

    /* Extract the UTF-16 string */
    gchar *utf16_string = tvb_get_string_enc(wmem_packet_scope(), tvb, offset, length, ENC_UTF_16);

    /* Add to the protocol tree */
    proto_tree_add_string(tree, hf_name, tvb, offset, length, utf16_string);

    /* Update the data pointer if needed */
    if (data) {
        *data = utf16_string;
    }

    /* Return the updated offset */
    return offset + length;
}

